def calculate_sequence(N):
    # Initialize the sequence storage
    a = {}
    a[1] = 1
    a[2] = 1

    for n in range(3, N + 1):
        # Recurrence: a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        a_prev = a[n-1]

        # Check arguments validity (they must be positive integers)
        arg1 = a_prev
        arg2 = n - a_prev

        if arg1 not in a or arg2 not in a:
            # This should not happen if the sequence is well-defined and a_k >= 1
            print(f"Error: Arguments {arg1} or {arg2} not found for n={n}")
            return None

        a_n = a[arg1] + a[arg2]
        a[n] = a_n

    return a

